def solve(di):
    cnt=collections.Counter(x for r in di for x in r)
    bg=cnt.most_common(1)[0][0]
    colmap=collections.defaultdict(list)
    for r in range(len(di)):
        for c in range(len(di[0])):
            if di[r][c]!=bg: colmap[di[r][c]].append((r,c))
    cands=[]
    for k,v in colmap.items():
        rs=[x for x,y in v]; cs=[y for x,y in v]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        if len(v)==4 and all(r0<=x<=r1 and c0<=y<=c1 for x,y in v) and \
           {(r0,c0),(r0,c1),(r1,c0),(r1,c1)}==set(v):
            cands.append(k)
    M=cands[0]
    cells=set()
    for r in range(len(di)):
        for c in range(len(di[0])):
            if di[r][c]==M: cells.add((r,c))
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    H,W=r1-r0+1,c1-c0+1
    win=[[di[r0+i][c0+j] for j in range(W)] for i in range(H)]
    noise=[(r,c,di[r][c]) for r in range(len(di)) for c in range(len(di[0])) if di[r][c]!=bg and not(r0<=r<=r1 and c0<=c<=c1)]
    seq=tuple(sorted(noise,key=lambda t:(t[2],t[0],t[1]))[::1])
    objcells={(r,c) for r in range(1,H-1) for c in range(1,W-1) if win[r][c]!=M}
    O=[row[:] for row in win]
    idx=0
    while idx<len(seq):
        val=seq[idx]; idx+=1
        # place next block of filler color into background slots in row-major order
        found=False
        for r in range(1,H-1):
            for cc in range(1,W-1):
                if O[r][cc]==bg:
                    O[r][cc]=val; found=True; break
            if found: break
    return O

