def components(m,sym=True):
    m=np.array(m); seen=np.zeros_like(m,bool); comps=[]
    for r in range(m.shape[0]):
        for c in range(m.shape[1]):
            if not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; comp=[]
                while stack:
                    p=stack.pop(); comp.append(p)
                    for dr in([-1,0,1] if sym else [-1,1,0,0] if False else None) : pass
                break
            elif sym:
                nbrs=[(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if abs(dr)+abs(dc)<=1 and 0<=r+dr<m.shape[0] and 0<=c+dc<m.shape[1]]
                seen[r,c]=True; cells=[]; col=m[p[0],p[1]]
                for nr,nc in nbrs:
                    if 0<=nr<m.shape[0] and 0<=nc<m.shape[1] and not seen[nr,nc] and m[nr,nc]==col:
                        stack.append((nr,nc)); seen[nr,nc]=True
                cells=list(stack)
                comps.append(((cells,col)))
            else:
                nb=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
                st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    p=st.pop(); cells.append(p)
                    for q in nb:
                        nr,nc=p[0]+q[0],p[1]+q[1]
                        if 0<=nr<m.shape[0] and 0<=nc<m.shape[1] and not seen[nr,nc] and m[nr,nc]==col:
                            st.append(q)
                comps.append(cells)
    return comps
