def cc(A,bg):
    H,W=len(A),len(A[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if A[i][j]!=bg and not seen[i][j]:
                col=A[i][j]; q=[(i,j)]; c=[(i,j)]; seen[i][j]=True
                while q:
                    x,y=q.pop()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+di,y+dj
                        if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and A[nx][ny]==col:
