def bestshift(A,B,bga=None,bgb=None):
    H,W=len(A),len(A[0]); h,w=len(B),len(B[0])
    best=(0,None,None)
    for i in range(-min(H,h),H-h+1):
        for j in range(-min(W,w),W-w+1):
            if i<0 or j<0: continue
            mm=sum(1 for x in range(h) for y in range(w) if 0<=i+x<H and 0<=j+y<W and A[i+x][j+y]==B[x][y])
            if mm>best[0]: best=(mm,i,j)
    return best
for n in range(1,9):
    Ai,Bi=D[f'Demo pair {n} input'],D[f'Demo pair {n} output']
    b,a=bestshift(Ai,Bi)[1:]
    print('demo',n,'shift',(b,a),'overlap',bestshift(Ai,Bi)[0],'of',len(Bi)*len(Bi[0]),'in',len(Ai)*len(Ai[0]))
